import type { ProjectStandardsReview, LessonStandardTarget } from '../shared/project-lessons/standards-review.models';

// Review annotations only. These do not award mastery or change published activity rules.
const target = (
  standardId: string,
  addressed: string,
  evidence: string,
  addition?: string,
): LessonStandardTarget => ({ standardId, addressed, evidence, ...(addition ? { addition } : {}) });

const review = (
  projectId: string,
  projectVersion: string,
  grade: 4 | 5 | 6,
  scope: string,
  lessons: readonly (readonly LessonStandardTarget[])[],
  planVersion = '1.0.0',
): ProjectStandardsReview => ({
  projectId, projectVersion, planVersion, grade, scope,
  lessons: lessons.map((targets, index) => ({ number: index + 1, targets })),
});

